const b = ($json && $json.body) ? $json.body : $json;
const cd = b.customData || {};
const is_fallback = (b.fallback === true || b.fallback === 'true');
return { json: {
  contact_id: String(b.contact_id || cd.contact_id || '').trim(),
  call_id: String(b.call_id || cd.call_id || '').trim(),
  is_fallback: is_fallback
}};

const gc = $json || {};
const contact = gc.contact || gc || {};
const cf = id => { const f = (contact.customFields || []).find(x => x.id === id); return f ? (f.value !== undefined ? f.value : f.field_value) : ''; };
const norm = $('Normalize').item.json;
const is_fallback = !!norm.is_fallback;

const DISP='YxGIrvPl5tfLeYoc7Ldr', NOTES='kVU8T6Swsh9sF4TWC81U',
      CTX='HW0eBfoQPW2mwxX8aY7Q', STATE='BD9TmgEynOEy6bCvZshm', TX='2j4uCLLeAbtj8sDTS84o';

// current human input
let disposition = String(cf(DISP) || '').trim();
let note        = String(cf(NOTES) || '').trim();

// stored context + state + transcript (written by Capture / Cold Handler)
let ctx = {};   try { ctx   = JSON.parse(String(cf(CTX)   || '{}')) || {}; } catch(e) {}
let state = {}; try { state = JSON.parse(String(cf(STATE) || '{}')) || {}; } catch(e) {}
const transcript = String(cf(TX) || '');
const processed  = !!state.processed;

// FALLBACK: ignore any (possibly stale) field values -> AI-only
if (is_fallback) { disposition = ''; note = ''; }

// signature of what we'd process
const dispo_norm = disposition ? disposition.toLowerCase().replace(/\s+/g, '-') : '';
const signature = dispo_norm + '|' + note;

// ---- GATE ----
let proceed = true, stop_reason = '';
if (is_fallback) {
  if (processed) { proceed = false; stop_reason = 'fallback-after-processed'; }   // downgrade guard
} else {
  if (!disposition && !note) { proceed = false; stop_reason = 'empty-input'; }     // ignore a clear
}
if (proceed && processed && signature === String(state.last_signature || '')) {
  proceed = false; stop_reason = 'duplicate';                                      // identical re-fire
}

const route = String(ctx.route || 'none').trim();

// handler input contract
return { json: {
  proceed: proceed, stop_reason: stop_reason, route: route, is_fallback: is_fallback,
  contact_id: String(contact.id || norm.contact_id || '').trim(),
  disposition: disposition, note: note, transcript: transcript, signature: signature,
  opp_id: String(ctx.opp_id || '').trim(),
  caller_N: ctx.caller_N || 0,
  call_id: String(ctx.call_id || norm.call_id || '').trim(),
  stage_name: String(ctx.stage_name || '').trim(),
  call_duration: String(ctx.call_duration || '').trim(),
  call_recording_url: String(ctx.call_recording_url || '').trim(),
  last_event_log_entry: String(state.last_event_log_entry || ''),
  last_call_summary_entry: String(state.last_call_summary_entry || ''),
  last_signature: String(state.last_signature || ''),
  company_name: String(contact.companyName || contact.contactName || '').trim(),
  contact: contact
}};
